//! Real hybrid fixture: file tree parsing, path sanitization, `piece
//! layers` load-time validation and v1 dual-representation consistency.
//!
//! The fixture was generated by the official BEP-52/BEP-47 creator
//! algorithm, verified against libtorrent 2.1.1.0 (see
//! tests/fixtures/README.md and hybrid_info_hash.rs). This test asserts:
//! 1. `filetree::parse` accepts the fixture (including the per-file
//!    layer->root re-validation);
//! 2. FileEntry roots/layers match the fixture bytes (hardcoded
//!    expectations taken from the fixture itself, whose infohashes are
//!    locked by the libtorrent engine);
//! 3. file tree DFS order == the v1 `files` list order (minus `.pad`;
//!    BEP-47 pads exist only in the v1 layout) — the hybrid
//!    dual-representation consistency (SPEC §4.2).

use std::fs;
use std::path::Path;

use taiji_bt::bencode::{self, Value};
use taiji_bt::filetree;

// Taken from the fixture (a libtorrent-verified creator product); see above.
const EXPECTED_ROOT_A: &str = "82774b06e8180ed739b6afc00cacd7cc0a29faa2dcf2d54229e0b976fea4515e";
const EXPECTED_ROOT_B: &str = "eb075fa68105158a2e21590faec188971ed102d78185207a2c6c1b4d54a3de7c";

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn get<'a>(value: &'a Value, key: &[u8]) -> &'a Value {
    match value.get(key) {
        Some(v) => v,
        None => panic!("missing dict key {key:?}"),
    }
}

fn root_of(entry: &filetree::FileEntry, what: &str) -> [u8; 32] {
    match entry.pieces_root {
        Some(r) => r,
        None => panic!("{what}: missing pieces root"),
    }
}

#[test]
fn hybrid_fixture_filetree_parses_and_validates() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/hybrid_16k.torrent");
    let torrent = match fs::read(&path) {
        Ok(b) => b,
        Err(e) => panic!("read fixture {path:?}: {e}"),
    };
    let top = match bencode::decode(&torrent) {
        Ok(v) => v,
        Err(e) => panic!("decode fixture: {e:?}"),
    };

    // parse re-derives each file's layer->root (the BEP-52 load check);
    // passing at all proves store::merkle's math matches real creator
    // output.
    let files = match filetree::parse(&top) {
        Ok(f) => f,
        Err(e) => panic!("filetree::parse must accept the libtorrent-validated fixture: {e}"),
    };

    assert_eq!(files.piece_length, 16384);
    assert_eq!(files.files.len(), 2, "fixture has two real files");

    let (a, b) = (&files.files[0], &files.files[1]);
    assert_eq!(a.path, Path::new("a.bin"));
    assert_eq!(a.length, 70000);
    assert_eq!(hex(&root_of(a, "a.bin")), EXPECTED_ROOT_A);
    assert_eq!(
        a.piece_layer.as_ref().map(|l| l.len()),
        Some(160),
        "a.bin: 5 x 32B piece roots (70000B / 16KiB pieces, ceil = 5)"
    );

    assert_eq!(b.path, Path::new("b.bin"));
    assert_eq!(b.length, 30000);
    assert_eq!(hex(&root_of(b, "b.bin")), EXPECTED_ROOT_B);
    assert_eq!(
        b.piece_layer.as_ref().map(|l| l.len()),
        Some(64),
        "b.bin: 2 piece roots"
    );
    assert_eq!(
        a.v1_offset, None,
        "v1_offset is filled by the layout mapping; always None at parse time"
    );

    // v1 dual-representation consistency: file tree DFS order == the v1
    // files list order (minus .pad).
    let info = get(&top, b"info");
    let v1_files = match get(info, b"files") {
        Value::List(l) => l,
        v => panic!("v1 files not a list: {v:?}"),
    };
    let v1_real: Vec<(&Vec<Value>, i64)> = v1_files
        .iter()
        .filter_map(|f| {
            let length = match f.get(b"length") {
                Some(Value::Int(n)) => *n,
                _ => panic!("v1 file without length"),
            };
            let path = match f.get(b"path") {
                Some(Value::List(p)) => p,
                _ => panic!("v1 file without path"),
            };
            // .pad placeholders (attr p) exist only in the v1 layout, not
            // the file tree (BEP-47).
            let is_pad = matches!(f.get(b"attr"), Some(Value::Bytes(b)) if b == b"p");
            if is_pad { None } else { Some((path, length)) }
        })
        .collect();
    assert_eq!(
        v1_real.len(),
        files.files.len(),
        "both representations agree on file count after pad removal"
    );
    for (entry, (v1_path, v1_len)) in files.files.iter().zip(v1_real) {
        let expected: Vec<&[u8]> = v1_path
            .iter()
            .map(|c| match c {
                Value::Bytes(b) => b.as_slice(),
                v => panic!("v1 path component not bytes: {v:?}"),
            })
            .collect();
        let got: Vec<&[u8]> = entry
            .path
            .components()
            .map(|c| c.as_os_str().as_encoded_bytes())
            .collect();
        assert_eq!(
            got, expected,
            "file tree matches v1 files paths (DFS order)"
        );
        assert_eq!(
            entry.length as i64, v1_len,
            "file tree matches v1 files lengths"
        );
    }
}
